import React from "react";
import "./Layout.css";

const Layout = ({ main, asideIzq, asideDer }) => {
  return (
    <div className="layout-grid">
      {asideIzq}
      {main}
      {asideDer}
      <footer className="layout-footer">
        <p>© 2025 MySpace - Todos los derechos reservados</p>
      </footer>
    </div>
  );
};

export default Layout;
